('Emma Rodriguez', 'Partner', 'Hansom Horses', 'Reon created a Make.com workflow that automatically sends follow-up emails to leads and updates our CRM. Our response time improved dramatically.', 5, 'manual', 2, true),
('David Park', 'Founder', 'Circle Flow', 'The automation Reon built processes our orders, sends tracking info, and handles returns automatically. It saves us 20+ hours every week.', 5, 'manual', 3, true),
('Jessica Miller', 'Investment Director', 'Anthro Capital', 'Reon set up GoHighLevel automations for our class bookings and reminders. Our no-show rate dropped by 60% and clients love the smooth experience.', 5, 'manual', 4, true);
